  // src/integrations/web-mcp.js
  function registerWebMcp({
    state,
    gpsPending: gpsPending2,
    selectFile,
    document: document2 = globalThis.document,
    navigator = globalThis.navigator
  }) {
    const context = document2.modelContext ?? navigator.modelContext;
    if (!context?.registerTool) return;
    let disposed = false;
    const lifetime = new AbortController();
    const register = (tool) => {
      try {
        const execute = tool.execute;
        Promise.resolve(
          context.registerTool(
            {
              ...tool,
              execute: (...args) => {
                if (disposed) throw new Error("Application has been disposed");
                return execute(...args);
              }
            },
            { signal: lifetime.signal }
          )
        ).catch(() => {
        });
      } catch {
      }
    };
    register({
      name: "list_hiking_routes",
      description: "List GPX routes imported by the user; no exact coordinates returned.",
      inputSchema: { type: "object", properties: {} },
      annotations: { readOnlyHint: true, untrustedContentHint: true },
      execute: async () => ({
        content: [
          {
            type: "text",
            text: JSON.stringify(
              state.library.map((file) => ({
                id: file.id,
                name: file.name,
                km: file.stats.km,
                selected: file.id === state.selected
              }))
            )
          }
        ]
      })
    });
    register({
      name: "select_hiking_route",
      description: "Select one imported GPX for planning. Does not start GPS, import, delete, or play.",
      inputSchema: { type: "object", properties: { id: { type: "string" } }, required: ["id"] },
      annotations: { readOnlyHint: false, untrustedContentHint: false },
      execute: async ({ id: id2 }) => {
        if (gpsPending2()) throw new Error("Finish and close GPS recording first.");
        if (!state.library.some((file) => file.id === id2)) throw new Error("Unknown GPX route.");
        selectFile(id2);
        return { content: [{ type: "text", text: "Route selected for planning." }] };
      }
    });
    return {
      dispose: () => {
        disposed = true;
        lifetime.abort();
      }
    };
  }

